for lang, files in T.items():
    loc = Path("locale", lang)
    loc.mkdir(parents=True, exist_ok=True)
    line = ABOUT_YOURSELF.get(lang)
    if line:  # "tell me about yourself" tells the story now
        who = loc / "who_are_you.intent"
        who.write_text("\n".join(l for l in who.read_text(encoding="utf-8").split("\n")
                                 if l.strip() and l.strip() != line) + "\n", encoding="utf-8")
    for name, lines in files.items():
        (loc / name).write_text("\n".join(lines) + "\n", encoding="utf-8")
    print(lang, len(files), "files")
